"""Envelope encryption for tenant keys (format keymgr-envelope-v1).

A fresh 256-bit data key (DEK) seals the plaintext with AES-256-GCM; the DEK is
then wrapped by the named key version (the key-encryption key, KEK):

* ``AES256`` KEK: the DEK is wrapped with AES-256-GCM (wrap scheme
  ``AES-GCM``);
* ``RSA2048`` KEK: the DEK is wrapped with RSA-OAEP-SHA256
  (``RSA-OAEP-SHA256``).

The envelope is one base64 token whose JSON payload carries only metadata and
wrapped material: ``key_id``, ``version``, the algorithm/schemes, the GCM
nonce/tag/ciphertext, the wrapped DEK and the authenticated AAD. Raw private
keys, data keys and passphrases never enter the envelope; the data key exists
only in process memory for the duration of one call.
"""

import base64
import binascii
import json
import os
from dataclasses import dataclass
from typing import Optional

from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding, rsa
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

FORMAT = "keymgr-envelope-v1"

# Content encryption is always AES-256-GCM under the ephemeral data key.
ENC_AES_GCM = "AES-GCM"
# KEK wrap schemes.
WRAP_AES_GCM = "AES-GCM"
WRAP_RSA_OAEP_SHA256 = "RSA-OAEP-SHA256"

_AES256 = "AES256"
_RSA2048 = "RSA2048"
_KEY_LEN = 32
_NONCE_LEN = 12
_TAG_LEN = 16
_RSA_WRAP_LEN = 256  # RSA-2048 OAEP ciphertext length.

_OAEP = padding.OAEP(
    mgf=padding.MGF1(algorithm=hashes.SHA256()),
    algorithm=hashes.SHA256(),
    label=None,
)


class EnvelopeError(ValueError):
    """An envelope request failure (always surfaced as 400)."""


@dataclass(frozen=True)
class OpenedEnvelope:
    """Structurally validated, still-encrypted envelope contents."""

    key_id: str
    version: int
    algorithm: str
    enc: str
    wrap: str
    nonce: bytes
    tag: bytes
    ciphertext: bytes
    wrapped_key: bytes
    wrap_nonce: Optional[bytes]
    aad: bytes


def b64_decode_field(value, field: str) -> bytes:
    """Strictly decode standard base64 (padding required).

    Raises EnvelopeError naming the request field on any non-string or
    non-canonical input.
    """
    if not isinstance(value, str):
        raise EnvelopeError("field %s must be a base64 string" % field)
    if value == "":
        return b""
    try:
        raw = base64.b64decode(value.encode("ascii"), validate=True)
    except (ValueError, TypeError, binascii.Error) as exc:
        raise EnvelopeError(
            "field %s is not valid base64" % field
        ) from exc
    return raw


def b64_encode(raw: bytes) -> str:
    """Canonical standard base64 encoding used for every envelope token."""
    return base64.b64encode(raw).decode("ascii")


def _wrap_dek_with(algorithm: str, kek, dek: bytes) -> tuple:
    """Wrap an existing DEK under the KEK. Returns (wrapped_key, wrap_nonce)."""
    if algorithm == _AES256:
        if not isinstance(kek, (bytes, bytearray)) or len(kek) != _KEY_LEN:
            raise EnvelopeError("server key material is invalid for AES256")
        wrap_nonce = os.urandom(_NONCE_LEN)
        sealed = AESGCM(bytes(kek)).encrypt(wrap_nonce, dek, None)
        return sealed, wrap_nonce
    if algorithm == _RSA2048:
        if not isinstance(kek, rsa.RSAPrivateKey) or kek.key_size != 2048:
            raise EnvelopeError(
                "server key material is invalid for RSA2048"
            )
        sealed = kek.public_key().encrypt(dek, _OAEP)
        return sealed, None
    raise EnvelopeError("unsupported algorithm for envelope: %r" % algorithm)


def _wrap_dek(algorithm: str, kek) -> tuple:
    """Wrap a fresh 32-byte DEK under the KEK. Returns (dek, wk, wrap_nonce)."""
    dek = os.urandom(_KEY_LEN)
    sealed, wrap_nonce = _wrap_dek_with(algorithm, kek, dek)
    return dek, sealed, wrap_nonce


def _unwrap_dek(opened: "OpenedEnvelope", kek) -> bytes:
    """Recover the DEK from the envelope using the KEK."""
    try:
        if opened.algorithm == _AES256:
            if not isinstance(kek, (bytes, bytearray)) or len(kek) != _KEY_LEN:
                raise EnvelopeError(
                    "server key material is invalid for AES256"
                )
            if opened.wrap_nonce is None:
                raise InvalidTag("missing wrap nonce")
            return AESGCM(bytes(kek)).decrypt(
                opened.wrap_nonce, opened.wrapped_key, None
            )
        if opened.algorithm == _RSA2048:
            if not isinstance(kek, rsa.RSAPrivateKey) or kek.key_size != 2048:
                raise EnvelopeError(
                    "server key material is invalid for RSA2048"
                )
            return kek.decrypt(opened.wrapped_key, _OAEP)
    except InvalidTag as exc:
        raise EnvelopeError(
            "field envelope is tampered or cannot be authenticated"
        ) from exc
    except ValueError as exc:
        # RSA decryption failures (wrong key/size/padding) land here.
        raise EnvelopeError(
            "field envelope is tampered or cannot be authenticated"
        ) from exc
    raise EnvelopeError(
        "field envelope is tampered or cannot be authenticated"
    )


def encode_envelope(
    *,
    key_id: str,
    version: int,
    algorithm: str,
    kek,
    plaintext: bytes,
    aad: Optional[bytes] = None,
) -> str:
    """Seal plaintext under a fresh data key wrapped by the KEK.

    Returns the opaque base64 envelope token. The KEK is the raw 32-byte key
    for AES256 or a loaded 2048-bit RSA private key for RSA2048 (its public
    component wraps the DEK).
    """
    if aad is None:
        aad = b""
    dek, wrapped_key, wrap_nonce = _wrap_dek(algorithm, kek)
    nonce = os.urandom(_NONCE_LEN)
    sealed = AESGCM(dek).encrypt(nonce, plaintext, aad)
    ciphertext, tag = sealed[:-_TAG_LEN], sealed[-_TAG_LEN:]
    wrap = WRAP_AES_GCM if algorithm == _AES256 else WRAP_RSA_OAEP_SHA256
    payload = {
        "format": FORMAT,
        "key_id": key_id,
        "version": version,
        "algorithm": algorithm,
        "enc": ENC_AES_GCM,
        "wrap": wrap,
        "nonce": b64_encode(nonce),
        "tag": b64_encode(tag),
        "ciphertext": b64_encode(ciphertext),
        "wrapped_key": b64_encode(wrapped_key),
        "aad": b64_encode(aad),
    }
    if wrap_nonce is not None:
        payload["wrap_nonce"] = b64_encode(wrap_nonce)
    raw = json.dumps(
        payload, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")
    return b64_encode(raw)


def _require_str(obj: dict, name: str) -> str:
    value = obj.get(name)
    if not isinstance(value, str) or not value:
        raise EnvelopeError("field envelope has missing or invalid %s" % name)
    return value


def _require_b64(obj: dict, name: str, *, allow_empty: bool = False) -> bytes:
    value = obj.get(name)
    if not isinstance(value, str):
        raise EnvelopeError("field envelope has missing or invalid %s" % name)
    if not value and not allow_empty:
        raise EnvelopeError("field envelope has missing or invalid %s" % name)
    try:
        return base64.b64decode(value.encode("ascii"), validate=True)
    except (ValueError, TypeError, binascii.Error) as exc:
        raise EnvelopeError(
            "field envelope has invalid base64 in %s" % name
        ) from exc


def decode_envelope(token: str) -> OpenedEnvelope:
    """Parse and structurally validate an envelope token (no crypto).

    Raises EnvelopeError (surfaced as 400) naming ``field envelope`` for any
    malformed, truncated, tampered-shape or unsupported-format token.
    """
    if not isinstance(token, str) or not token:
        raise EnvelopeError("field envelope must be a non-empty string")
    try:
        raw = base64.b64decode(token.encode("ascii"), validate=True)
    except (ValueError, TypeError, binascii.Error) as exc:
        raise EnvelopeError("field envelope is not valid base64") from exc
    try:
        obj = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise EnvelopeError(
            "field envelope does not contain a valid JSON object"
        ) from exc
    if not isinstance(obj, dict):
        raise EnvelopeError(
            "field envelope does not contain a valid JSON object"
        )
    if obj.get("format") != FORMAT:
        raise EnvelopeError("field envelope format must be %r" % FORMAT)
    key_id = _require_str(obj, "key_id")
    version = obj.get("version")
    if (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version < 1
    ):
        raise EnvelopeError(
            "field envelope version must be a positive integer"
        )
    algorithm = obj.get("algorithm")
    if algorithm not in (_AES256, _RSA2048):
        raise EnvelopeError(
            "field envelope algorithm must be one of: AES256, RSA2048"
        )
    expected_wrap = (
        WRAP_AES_GCM if algorithm == _AES256 else WRAP_RSA_OAEP_SHA256
    )
    if obj.get("enc") != ENC_AES_GCM:
        raise EnvelopeError("field envelope enc must be %r" % ENC_AES_GCM)
    if obj.get("wrap") != expected_wrap:
        raise EnvelopeError(
            "field envelope wrap must be %r for algorithm %s"
            % (expected_wrap, algorithm)
        )
    nonce = _require_b64(obj, "nonce")
    tag = _require_b64(obj, "tag")
    if len(nonce) != _NONCE_LEN:
        raise EnvelopeError("field envelope nonce must be 12 bytes")
    if len(tag) != _TAG_LEN:
        raise EnvelopeError("field envelope tag must be 16 bytes")
    ciphertext = _require_b64(obj, "ciphertext", allow_empty=True)
    wrapped_key = _require_b64(obj, "wrapped_key")
    wrap_nonce = None
    if algorithm == _AES256:
        wrap_nonce = _require_b64(obj, "wrap_nonce")
        if len(wrap_nonce) != _NONCE_LEN:
            raise EnvelopeError(
                "field envelope wrap_nonce must be 12 bytes"
            )
        # AES-GCM of a 32-byte DEK is exactly 48 bytes (32 + 16 tag).
        if len(wrapped_key) != _KEY_LEN + _TAG_LEN:
            raise EnvelopeError(
                "field envelope wrapped_key has an invalid length"
            )
    else:
        if len(wrapped_key) != _RSA_WRAP_LEN:
            raise EnvelopeError(
                "field envelope wrapped_key has an invalid length"
            )
        if "wrap_nonce" in obj and obj["wrap_nonce"] is not None:
            raise EnvelopeError(
                "field envelope wrap_nonce must be absent for RSA2048"
            )
    aad = b""
    if "aad" in obj and obj["aad"] is not None:
        aad = _require_b64(obj, "aad", allow_empty=True)
    return OpenedEnvelope(
        key_id=key_id,
        version=version,
        algorithm=algorithm,
        enc=ENC_AES_GCM,
        wrap=expected_wrap,
        nonce=nonce,
        tag=tag,
        ciphertext=ciphertext,
        wrapped_key=wrapped_key,
        wrap_nonce=wrap_nonce,
        aad=aad,
    )


def open_envelope(opened: OpenedEnvelope, kek) -> bytes:
    """Unwrap the data key and decrypt the payload (AES/RSA KEK).

    A wrong key version, a modified nonce/tag/ciphertext/wrapped_key or a
    failed RSA unpadding all fail as one field-naming authentication error;
    the caller separately checks that the request AAD equals the envelope AAD.
    """
    dek = _unwrap_dek(opened, kek)
    try:
        sealed = opened.ciphertext + opened.tag
        return AESGCM(dek).decrypt(opened.nonce, sealed, opened.aad)
    except InvalidTag as exc:
        raise EnvelopeError(
            "field envelope is tampered or cannot be authenticated"
        ) from exc


def _decrypt_content(opened: OpenedEnvelope, dek: bytes) -> bytes:
    """Decrypt the payload with an already-recovered 32-byte data key."""
    sealed = opened.ciphertext + opened.tag
    return AESGCM(dek).decrypt(opened.nonce, sealed, opened.aad)


def open_envelope_native(opened: OpenedEnvelope, provider, handle: str) -> bytes:
    """Decrypt via a KMS/HSM-native ``unwrap_key`` provider operation.

    The data key is unwrapped INSIDE the provider by its bound KEK: the
    service never calls ``export_material`` and never loads the KEK private
    material into this process. The provider returns the 32-byte DEK and the
    payload is then authenticated/decrypted here.

    Provider error mapping follows the provider contract unchanged: an
    authentication failure raises ``ProviderInvalidMaterial`` (surfaced as a
    400 naming the envelope); an unknown/algorithm-mismatched handle or any
    backend failure raises ``ProviderUnavailable`` (the fixed 503, no audit
    event); an unexpected ``ValueError``/``TypeError`` from the provider is a
    contract violation and is normalized to ``ProviderUnavailable``. A failed
    content authentication raises :class:`EnvelopeError`.
    """
    from .provider import (
        ProviderInvalidMaterial,
        ProviderUnavailable,
    )

    try:
        dek = provider.unwrap_key(
            handle, opened.wrapped_key, opened.wrap_nonce
        )
    except (ProviderInvalidMaterial, ProviderUnavailable):
        raise
    except (ValueError, TypeError) as exc:
        # A conforming provider cannot raise these for a structurally valid
        # envelope: treat it as a backend/contract fault, never a 400 path
        # with provider text.
        raise ProviderUnavailable(
            "provider unwrap_key raised a contract violation"
        ) from exc
    try:
        return _decrypt_content(opened, dek)
    except InvalidTag as exc:
        raise EnvelopeError(
            "field envelope is tampered or cannot be authenticated"
        ) from exc


def rewrap_envelope(
    opened: OpenedEnvelope,
    source_kek,
    *,
    target_version: int,
    target_algorithm: str,
    target_kek,
) -> str:
    """Re-wrap an authenticated envelope's data key under a new KEK version.

    The source envelope is fully authenticated first: the DEK is unwrapped
    with the source KEK and the content GCM tag is verified (the recovered
    plaintext is used only for that check, never stored or returned). Only
    then is the SAME data key wrapped under the target version's KEK. The
    key_id, nonce, tag, ciphertext and aad bytes are carried over unchanged;
    the version, algorithm and wrap fields are rebuilt for the target. The
    data key itself exists only in process memory for the duration of the
    call and never enters the returned token in the clear.
    """
    dek = _unwrap_dek(opened, source_kek)
    try:
        AESGCM(dek).decrypt(
            opened.nonce, opened.ciphertext + opened.tag, opened.aad
        )
    except InvalidTag as exc:
        raise EnvelopeError(
            "field envelope is tampered or cannot be authenticated"
        ) from exc
    wrapped_key, wrap_nonce = _wrap_dek_with(
        target_algorithm, target_kek, dek
    )
    wrap = (
        WRAP_AES_GCM
        if target_algorithm == _AES256
        else WRAP_RSA_OAEP_SHA256
    )
    payload = {
        "format": FORMAT,
        "key_id": opened.key_id,
        "version": target_version,
        "algorithm": target_algorithm,
        "enc": ENC_AES_GCM,
        "wrap": wrap,
        "nonce": b64_encode(opened.nonce),
        "tag": b64_encode(opened.tag),
        "ciphertext": b64_encode(opened.ciphertext),
        "wrapped_key": b64_encode(wrapped_key),
        "aad": b64_encode(opened.aad),
    }
    if wrap_nonce is not None:
        payload["wrap_nonce"] = b64_encode(wrap_nonce)
    raw = json.dumps(
        payload, separators=(",", ":"), sort_keys=True
    ).encode("utf-8")
    return b64_encode(raw)

    # persisted by an export, so a ledger failure after this point
    # simply fails the request with 500.
    bundle = store.export_bundle(key_id, tenant_id, passphrase)
    if bundle is None:
        # Unknown key and another tenant's key look identical.
        if not self._record_attempt(
            tenant_id, key_id, audit_mod.ACTION_EXPORT,
            audit_mod.OUTCOME_REJECTED,
        ):
            return
        self._send_json(404, {"error": "key not found"})
        return
    if not self._record_attempt(
        tenant_id, key_id, audit_mod.ACTION_EXPORT,
        audit_mod.OUTCOME_SUCCESS,
    ):
        return
    self._send_json(
        200, {"format": keybundle.FORMAT, "bundle": bundle}
    )

def _reject_crypto(self, tenant_id, key_id, action, status,
                   message) -> None:
    """Audit a rejected encrypt/decrypt attempt, then answer."""
    if not self._record_attempt(
        tenant_id, key_id, action, audit_mod.OUTCOME_REJECTED
    ):
        return
    self._send_json(status, {"error": message})

def _crypto_request_base(self, key_id, parts, action):
    """Shared parse/validate prelude for encrypt and decrypt.

    Returns ``(tenant_id, payload)`` or None after the response was
    sent. Follows the export endpoint's rules: body/tenant failures
    are invisible tenant_conflict events, and field errors after the
    tenant is known are tenant-visible rejected attempts. A malformed
    ``key_id`` is a parameter error answered as a plain, unaudited
    400 (it is a malformed value, not an existence probe), exactly
    like the other crypto endpoints.
    """
    payload = self._read_json_object()
    if payload is None:
        return None
    body_tenant = payload.get("tenant_id")
    if not isinstance(body_tenant, str) or not body_tenant:
        if not self._record_conflict():
            return None
        self._bad_request("field tenant_id must be a non-empty string")
        return None
    tenant_id = self._tenant(parts, payload)
    if tenant_id is None:
        return None
    if self._bad_key_id(key_id, audit=False):
        return None
    return tenant_id, payload

def _request_aad(self, tenant_id, key_id, action, payload):
    """Decode the optional aad field; None means 400 was sent."""
    aad = payload.get("aad")
    if aad is None:
        return b""
    try:
        return envelope.b64_decode_field(aad, "aad")
    except envelope.EnvelopeError as exc:
        self._reject_crypto(
            tenant_id, key_id, action, 400, str(exc)
        )
        return None

def _encrypt_key(self, key_id: str, parts, operator: str) -> None:
    """POST /v1/keys/{key_id}/encrypt (idempotent).

    Requires a single ``Idempotency-Key`` header, validated before the
    body is read. Every parse/parameter/field failure up to the bind is
    a side-effect-free 400 (no audit event, operation record or
    provider handle) and never consumes the key. Binding mints a UUID4
    operation_id; an identical binding replays the FIRST status,
    envelope and audit event byte-for-byte (the KEK/data key are never
    invoked twice), while the same key with a different request is a
    409 naming the original operation_id.

    Success is ``200 {"format", "envelope", "operation_id"}``. The
    answer carries only the opaque envelope token -- never the data
    key, the KEK, the plaintext, the AAD or any backend material. The
    plaintext/AAD never enter the operation or mirror records either:
    the binding stores only an HMAC commitment of them.
    """
    action = audit_mod.ACTION_ENCRYPT
    # Header first, before the body or any tenant/audit/provider work.
    idem_key = self._idempotency_key()
    if idem_key is None:
        return
    payload = self._read_json_object(audit=False)
    if payload is None:
        return
    body_tenant = payload.get("tenant_id")
    if not isinstance(body_tenant, str) or not body_tenant:
        self._bad_request("field tenant_id must be a non-empty string")
        return
    tenant_id = self._tenant(parts, payload, audit=False)
    if tenant_id is None:
        return
    if self._bad_key_id(key_id, audit=False):
        return
    version = payload.get("version")
    if version is not None and (
        not isinstance(version, int)
        or isinstance(version, bool)
        or version < 1
    ):
        self._bad_request(
            "field version must be a positive integer"
        )
        return
    plaintext = payload.get("plaintext")
    if not isinstance(plaintext, str):
        self._bad_request(
            "field plaintext must be a base64 string"
            if "plaintext" in payload
            else "missing required field: plaintext"
        )
        return
    try:
        raw_plaintext = envelope.b64_decode_field(
            plaintext, "plaintext"
        )
    except envelope.EnvelopeError as exc:
        self._bad_request(str(exc))
        return
    aad = b""
    if payload.get("aad") is not None:
        try:
            aad = envelope.b64_decode_field(payload.get("aad"), "aad")
        except envelope.EnvelopeError as exc:
            self._bad_request(str(exc))
            return
    # The binding compares the exact request, but plaintext/AAD must
    # never be persisted: store only an opaque keyed commitment of the
    # canonical (decoded) secret fields in the normalized binding.
    binding_payload = dict(payload)
    binding_payload["plaintext"] = operation_store.audit.commitment(
        "plaintext:" + envelope.b64_encode(raw_plaintext)
    )
    if payload.get("aad") is not None:
        binding_payload["aad"] = operation_store.audit.commitment(
            "aad:" + envelope.b64_encode(aad)
        )

    def execute(operation, mirror=None):
        # Kind and the exact key_id rule are durable before the policy
        # check, so any bound terminal replays from context alone.
        operation_store.update_details(
            operation, {"kind": "encrypt", "key_id": key_id}
        )
        if mirror is not None:
            mirror.describe(
                {"kind": "encrypt", "write_set": [key_id]}
            )
        # Authorization follows validation and precedes existence.
        if not policy_store.is_allowed(
            tenant_id, action, operator
        ):
            return self._idempotent_rejection(
                operation, tenant_id, key_id, action, 403,
                "action not permitted by policy",
            )
        # Read-only resolve of the committed KEK under the per-key
        # locks. A contended key waits up to 5 s then fails as
        # timed_out (503) with no event/handle/envelope.
        status, _record, ver, kek = store.crypto_material(
            key_id, tenant_id, version,
            lock_timeout=operations_mod.LOCK_WAIT_SECONDS,
        )
        if status == store.CRYPTO_NOT_FOUND:
            # Unknown key/version and cross-tenant access are
            # indistinguishable, all 404.
            return self._idempotent_rejection(
                operation, tenant_id, key_id, action, 404,
                "key not found",
            )
        if status == store.CRYPTO_REVOKED:
            return self._idempotent_rejection(
                operation, tenant_id, key_id, action, 409,
                "key is revoked",
            )
        token = envelope.encode_envelope(
            key_id=key_id,
            version=ver.version,
            algorithm=ver.algorithm,
            kek=kek,
            plaintext=raw_plaintext,
            aad=aad,
        )
        body = {
            "format": envelope.FORMAT,
            "envelope": token,
            "operation_id": operation.operation_id,
        }
        # Stage the exact 200 body, then make the single success
        # event named after the operation_id the commit point: only
        # after it is durable is the envelope released. A crash
        # before this leaves the op pending with no answer and no
        # event; a restart/retry seals again exactly once.
        operation_store.finalize_durable(
            operation,
            200,
            body,
            audit={
                "action": action,
                "outcome": audit_mod.OUTCOME_SUCCESS,
                "tenant_id": tenant_id,
                "key_id": key_id,
            },
        )
        if mirror is not None:
            # Read-only: no journal/handle/key marker. The mirror stays
            # at its bound phase and is discarded by after_terminal /
            # startup settlement once the event is durable and no
            # residual evidence survives, so the phase itself is never
            # advanced (and a phase-write fault cannot downgrade the
            # already-durable commit).
            pass
        return 200, body

    self._idempotent_guard(
        parts.path, tenant_id, operator, binding_payload,
        idem_key, execute,
    )

def _migrate_key(self, key_id: str, parts, operator: str) -> None:
    """POST /v1/keys/{key_id}/migrate (idempotent).

    Body is exactly ``{"tenant_id": T}`` and a single
    ``Idempotency-Key`` is required, validated (with every parse/
    parameter check) BEFORE the key is bound: such failures are
    side-effect-free 400s with no audit event, operation record, key
    change or provider handle. After binding, authorization is the
    ``migrate`` policy action, an unknown/foreign key is 404, and a
    key whose versions are all already on the ready provider is 409.
    Success is ``200 {"key_id","provider_id","versions",
    "operation_id"}``: the ready provider id and the ascending version
    list. A missing/unhealthy provider, a material mismatch or a
    timeout is the fixed 503; the body never carries material or a
    handle.
    """
    idem_key = self._idempotency_key()
    if idem_key is None:
        return
    payload = self._read_json_object(audit=False)
    if payload is None:
        return
    extra = [field for field in payload if field != "tenant_id"]
    if extra:
        self._bad_request(
            "field %s is not accepted by this endpoint" % extra[0]
        )
        return
    body_tenant = payload.get("tenant_id")
    if not isinstance(body_tenant, str) or not body_tenant:
        self._bad_request("field tenant_id must be a non-empty string")
        return
    tenant_id = self._tenant(parts, payload, audit=False)
    if tenant_id is None:
        return
    if self._bad_key_id(key_id, audit=False):
        return

    def execute(operation, mirror=None):
        operation_store.update_details(
            operation,
            {"kind": "migrate", "key_id": key_id},
        )
        if mirror is not None:
            mirror.describe(
                {"kind": "migrate", "write_set": [key_id]}
            )
        if not policy_store.is_allowed(
            tenant_id, audit_mod.ACTION_MIGRATE, operator
        ):
            return self._idempotent_rejection(
                operation, tenant_id, key_id,
                audit_mod.ACTION_MIGRATE, 403,
                "action not permitted by policy",
            )

        def stage_success(committed_record, provider_id, versions):
            # Runs after the rebound key file landed, before the
            # commit-point ledger append: the exact 200 body is
            # durable with the event and replayed verbatim.
            body = {
                "key_id": key_id,
                "provider_id": provider_id,
                "versions": versions,
                "operation_id": operation.operation_id,
            }
            operation_store.stage_terminal(operation, 200, body)

        try:
            result = store.migrate(
                key_id, tenant_id,
                event_id=operation.operation_id,
                lock_timeout=operations_mod.LOCK_WAIT_SECONDS,
                pre_commit=stage_success,
                mirror=mirror,
            )
        except KeyAlreadyMigrated:
            # Bound 409: every version is already on the ready
            # provider. No provider call, file change, handle or
            # success event happened; the conflict is a terminal like
            # any other bound refusal.
            return self._idempotent_rejection(
                operation, tenant_id, key_id,
                audit_mod.ACTION_MIGRATE, 409,
                "key is already managed by the ready provider",
            )
        except LockTimeout:
            # A contended key waits past the five-second budget: the
            # migrate made no provider call and wrote nothing, so keep
            # the op PENDING (mirror reset, no audit event) and answer
            # the endpoint's fixed provider 503 text; a same-key retry
            # continues under the same operation_id.
            raise ProviderReconnectPending(
                "migrate exceeded the shared five-second budget"
            )
        if result is None:
            return self._idempotent_rejection(
                operation, tenant_id, key_id,
                audit_mod.ACTION_MIGRATE, 404, "key not found",
            )
        _record, provider_id, versions = result
        return (
            200,
            {
                "key_id": key_id,
                "provider_id": provider_id,
                "versions": versions,
            },
        )

    self._idempotent_guard(
        parts.path, tenant_id, operator, payload, idem_key, execute
    )

def _decrypt_key(self, key_id: str, parts, operator: str) -> None:
    """POST /v1/keys/{key_id}/decrypt.

    Body ``{tenant_id, envelope, aad?}``. The envelope names its own
    key_id and version; both must match the request, the AAD must
    match the sealed one, and any tampering is a 400 naming the
    field. The plaintext leaves only inside the response body.
    """
    action = audit_mod.ACTION_DECRYPT
    base = self._crypto_request_base(key_id, parts, action)
    if base is None:
        return
    tenant_id, payload = base
    token = payload.get("envelope")
    if not isinstance(token, str) or not token:
        self._reject_crypto(
            tenant_id, key_id, action, 400,
            "field envelope must be a non-empty string",
        )
        return
    aad = self._request_aad(tenant_id, key_id, action, payload)
    if aad is None:
        return
    # Structural validation is parameter validation: it runs before
    # authorization, exactly like the other request fields.
    try:
        opened = envelope.decode_envelope(token)
    except envelope.EnvelopeError as exc:
        self._reject_crypto(
            tenant_id, key_id, action, 400, str(exc)
        )
        return
    if opened.key_id != key_id:
        self._reject_crypto(
            tenant_id, key_id, action, 400,
            "field envelope key_id does not match the request key_id",
        )
        return
    if not self._enforce(tenant_id, key_id, action, operator):
        return
    # Native DEK unwrap is requested by the provider, not the
    # request: when the bound provider declares unwrap_key the
    # resolve returns a NativeUnwrap pair and the KEK private
    # material never enters this process; otherwise the ordinary
    # export path yields a KEK object.
    status, record, ver, material = store.crypto_material(
        key_id, tenant_id, opened.version, native_unwrap=True
    )
    if status == store.CRYPTO_NOT_FOUND:
        self._reject_crypto(
            tenant_id, key_id, action, 404, "key not found"
        )
        return
    if status == store.CRYPTO_REVOKED:
        self._reject_crypto(
            tenant_id, key_id, action, 409, "key is revoked"
        )
        return
    if opened.algorithm != ver.algorithm:
        self._reject_crypto(
            tenant_id, key_id, action, 400,
            "field envelope algorithm does not match the key version",
        )
        return
    if opened.aad != aad:
        self._reject_crypto(
            tenant_id, key_id, action, 400,
            "field aad does not match the envelope",
        )
        return
    try:
        if isinstance(material, NativeUnwrap):
            # KMS/HSM-native DEK unwrap on the bound provider inside
            # the ordinary provider-call gate. An authentication
            # failure is a 400 naming the envelope; any provider
            # fault or malformed result is the fixed 503 (caught at
            # dispatch) and is never audited.
            with provider_mod.provider_call():
                plaintext = envelope.open_envelope_native(
                    opened, material.provider, material.handle
                )
        else:
            plaintext = envelope.open_envelope(opened, material)
    except ProviderInvalidMaterial:
        self._reject_crypto(
            tenant_id, key_id, action, 400,
            "field envelope is tampered or cannot be authenticated",
        )
        return
    except envelope.EnvelopeError as exc:
        self._reject_crypto(
            tenant_id, key_id, action, 400, str(exc)
        )
        return
    if not self._record_attempt(
        tenant_id, key_id, action, audit_mod.OUTCOME_SUCCESS
    ):
        return
    self._send_json(
        200, {"plaintext": envelope.b64_encode(plaintext)}
    )

def _rewrap_key(self, key_id: str, parts, operator: str) -> None:
    """POST /v1/keys/{key_id}/rewrap.

    Body is exactly ``{tenant_id, envelope, target_version?, aad?}``
    (non-idempotent, no Idempotency-Key). ``envelope`` and ``aad``
    are canonical standard base64; ``target_version`` defaults to the
    key's current version. An unparseable/non-object body, the UUID4
    key_id, the base64 fields, the envelope structure and an envelope
    key_id differing from the path are all parameter validation: a
    400 naming the field, written to no ledger. Only a wrong/missing
    tenant *source* records the invisible tenant_conflict.

    Authorization (``rewrap``) precedes existence: a denial is 403
    with a ``rewrap/rejected`` event carrying key_id. After that an
    unknown/cross-tenant key or an unknown version is 404, a revoked
    key or an already-current target is 409, an algorithm mismatch
    with the SOURCE version or a failed authentication is 400, and a
    provider/material failure is the fixed 503 text (not audited).
    Success rewraps the SAME authenticated data key under the target
    version: nonce, tag, ciphertext, aad and key_id bytes are carried
    over unchanged and the answer is
    ``200 {"format","envelope"}``. The data key, plaintext, handles
    and material never enter a response, the ledger or any file.
    """
    action = audit_mod.ACTION_REWRAP
    # Like sign/verify, a malformed body is a plain 400 with no
    # tenant_conflict: only an actual tenant-source failure below is
    # audited.
    payload = self._read_json_object(parse_conflict=False)
    if payload is None:
        return
    body_tenant = payload.get("tenant_id")
    if not isinstance(body_tenant, str) or not body_tenant:
        if not self._record_conflict():
            return
        self._bad_request("field tenant_id must be a non-empty string")
        return
    tenant_id = self._tenant(parts, payload)
    if tenant_id is None:
        return
    # A malformed key_id is parameter validation on this endpoint:
    # 400 with no event (the tenant source itself was valid).
    if self._bad_key_id(key_id, audit=False):
        return
    extra = [
        f for f in payload
        if f not in ("tenant_id", "envelope", "target_version", "aad")
    ]
    if extra:
        self._bad_request(
            "field %s is not accepted by this endpoint" % extra[0]
        )
        return
    target_version = payload.get("target_version")

"""A fake external KMS/HSM provider for recovery tests.

Loaded through the ``module:factory`` mechanism (``KEYMGR_PROVIDER``). State
lives in a JSON file named by ``FAKE_KMS_STATE`` so several *processes* (the
CLI, a server, a recovery sweep) share one backend, exactly like a real KMS.
Fault injection is driven by a JSON file named by ``FAKE_KMS_FAULTS``:

    {
      "unreachable": true,          # every call fails as a backend outage
      "fail": {"delete": true, ...} # per-operation failures
      "sleep": {"rotate": 5.0},     # per-operation pre-call delay (seconds)
      "health": false,              # health() returns False (unavailable)
      "health_raises": true,        # health() raises (treated as unavailable)
      "health_nonbool": "yes",      # health() returns a non-bool (unavailable)
      "health_sleep": 6.0,          # health() blocks past the reconnect budget
      "provider_id": "fakekms-alt"  # override the factory's provider_id
      "declare_sign": true,         # capabilities.operations gains "sign"
      "sign_not_callable": true,    # declare sign but break the method (contract)
      "sign_short": true,           # sign() returns a malformed short value
      "sign_tamper": true,          # sign() returns a flipped-byte signature
      "declare_unwrap_key": true,   # capabilities.operations gains "unwrap_key"
      "unwrap_not_callable": true,  # declare unwrap_key but break the method
      "unwrap_fail": true,          # unwrap_key() raises a backend fault
      "unwrap_short": true          # unwrap_key() returns a malformed short DEK
    }

Materials are stored base64-wrapped with a static prefix so nothing here ever
resembles plaintext, and handles are random UUIDs recorded in the state file.
Per-process per-operation call counts are exposed via ``call_count(op)`` so
tests can assert which provider operations a request actually used.
"""

import base64
import json
import os
import threading
import time
import uuid

from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import padding

PROVIDER_ID = "fakekms"

_lock = threading.Lock()


def _state_path():
    return os.environ["FAKE_KMS_STATE"]


def _faults_path():
    return os.environ.get("FAKE_KMS_FAULTS", "")


def _load_state():
    try:
        with open(_state_path(), "r", encoding="utf-8") as fh:
            return json.load(fh)
    except (OSError, ValueError):
        return {"handles": {}}


def _save_state(state):
    path = _state_path()
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(state, fh)
        fh.flush()
        os.fsync(fh.fileno())
    os.replace(tmp, path)


def _faults():
    path = _faults_path()
    if not path:
        return {}
    try:
        with open(path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return {}
    return data if isinstance(data, dict) else {}


_call_counts = {}


def reset():
    """Clear per-process fault counters (called by the test fixture)."""
    _call_counts.clear()


def call_count(op):
    """How many times operation ``op`` was entered in this process."""
    return _call_counts.get(op, 0)


def _check_fault(op):
    _call_counts[op] = _call_counts.get(op, 0) + 1
    faults = _faults()
    sleep = faults.get("sleep")
    if isinstance(sleep, dict) and op in sleep:
        time.sleep(float(sleep[op]))
    if faults.get("unreachable"):
        raise RuntimeError("backend is unreachable")
    fail = faults.get("fail")
    if isinstance(fail, dict) and fail.get(op):
        raise RuntimeError("backend failure in %s" % op)
    fail_after = faults.get("fail_after")
    if isinstance(fail_after, dict) and op in fail_after:
        if _call_counts[op] > int(fail_after[op]):
            raise RuntimeError("backend failure in %s" % op)


def _wrap(material):
    return "fk1." + base64.urlsafe_b64encode(material.encode("utf-8")).decode(
        "ascii"
    )


def _unwrap(blob):
    if not isinstance(blob, str) or not blob.startswith("fk1."):
        raise RuntimeError("not a fakekms blob")
    return base64.urlsafe_b64decode(blob[4:].encode("ascii")).decode("utf-8")


class FakeKmsProvider:
    def __init__(self):
        # The id can be overridden per process (FAKE_KMS_PROVIDER_ID) so a
        # reconnect can install a provider carrying a different provider_id,
        # exercising the pending-operation displacement rule.
        self.provider_id = os.environ.get("FAKE_KMS_PROVIDER_ID", PROVIDER_ID)
        if _faults().get("sign_not_callable"):
            # Contract-violation injection: the provider declares "sign" in
            # its capabilities but the attribute is not a callable method.
            self.sign = True
        if _faults().get("unwrap_not_callable"):
            # Contract-violation injection: declares "unwrap_key" without a
            # callable method.
            self.unwrap_key = True

    @property
    def capabilities(self):
        operations = [
            "generate",
            "rotate",
            "import_material",
            "export_material",
            "delete",
        ]
        if _faults().get("declare_sign"):
            operations.append("sign")
        if _faults().get("declare_unwrap_key"):
            operations.append("unwrap_key")
        return {
            "algorithms": ["AES256", "RSA2048"],
            "operations": operations,
        }

    def configure(self, data_dir):
        _check_fault("configure")

    def health(self):
        """Optional readiness probe driven by the faults file."""
        faults = _faults()
        if faults.get("health_raises"):
            raise RuntimeError("health endpoint is failing")
        if "health_nonbool" in faults:
            return faults.get("health_nonbool")
        if "health_sleep" in faults:
            time.sleep(float(faults["health_sleep"]))
        if "health" in faults:
            return bool(faults.get("health"))
        # Default: healthy unless the backend is globally unreachable.
        return not faults.get("unreachable")

    def _mint(self, algorithm, public_key, material):
        _check_fault("mint")
        handle = uuid.uuid4().hex
        with _lock:
            state = _load_state()
            state["handles"][handle] = {
                "algorithm": algorithm,
                "public_key": public_key,
                "material": _wrap(material),
            }
            _save_state(state)
        return {
            "handle": handle,
            "public_key": public_key,
            "encrypted_material": _wrap(material),
        }

    def generate(self, algorithm):
        _check_fault("generate")
        from keymgr.crypto import generate_key

        generated = generate_key(algorithm)
        return self._mint(
            algorithm, generated.public_material, generated.private_material
        )

    def rotate(self, algorithm):
        _check_fault("rotate")
        return self.generate(algorithm)

    def import_material(self, algorithm, public_key, material):
        _check_fault("import_material")
        if not isinstance(material, str) or not material:
            raise RuntimeError("empty material")
        return self._mint(algorithm, public_key, material)

    def export_material(self, handle):
        _check_fault("export_material")
        with _lock:
            state = _load_state()
            entry = state["handles"].get(handle)
            if entry is None:
                raise RuntimeError("unknown handle")
            return {
                "public_key": entry["public_key"],
                "encrypted_material": _unwrap(entry["material"]),
            }

    def sign(self, handle, message):
        """Optional native RSASSA-PKCS1-v1_5/SHA-256 signature (declared via
        the ``declare_sign`` fault key)."""
        if not isinstance(handle, str) or not handle:
            raise ValueError("sign requires a non-empty handle string")
        if not isinstance(message, bytes):
            raise TypeError("sign message must be bytes")
        _check_fault("sign")
        with _lock:
            state = _load_state()
            entry = state["handles"].get(handle)
        if entry is None:
            raise RuntimeError("unknown handle")
        if entry.get("algorithm") != "RSA2048":
            raise RuntimeError("handle is not an RSA2048 key")
        faults = _faults()
        if faults.get("sign_short"):
            # Contract-violation injection: a malformed, short signature.
            return b"short"
        private_key = serialization.load_pem_private_key(
            _unwrap(entry["material"]).encode("utf-8"), password=None
        )
        signature = private_key.sign(
            message, padding.PKCS1v15(), hashes.SHA256()
        )
        if faults.get("sign_tamper"):
            # Contract-violation injection: 256 bytes that do not verify.
            tampered = bytearray(signature)
            tampered[0] ^= 0x01
            return bytes(tampered)
        return signature

    def unwrap_key(self, handle, wrapped_key, wrap_nonce=None):
        """Optional native DEK unwrap (declared via ``declare_unwrap_key``).

        Implements the provider contract: argument ``ValueError``/
        ``TypeError`` rules, ``ProviderInvalidMaterial`` on an authentication
        failure, backend faults as plain exceptions (the service normalizes
        them to ProviderUnavailable).
        """
        if not isinstance(handle, str) or not handle:
            raise ValueError("unwrap_key requires a non-empty handle string")
        if not isinstance(wrapped_key, bytes):
            raise TypeError("unwrap_key wrapped_key must be bytes")
        if wrap_nonce is not None and not isinstance(wrap_nonce, bytes):
            raise TypeError("unwrap_key wrap_nonce must be bytes or None")
        if not wrapped_key:
            raise ValueError("unwrap_key wrapped_key must be non-empty")
        _check_fault("unwrap_key")
        if _faults().get("unwrap_fail"):
            raise RuntimeError("backend failure in unwrap_key")
        with _lock:
            state = _load_state()
            entry = state["handles"].get(handle)
        if entry is None:
            raise RuntimeError("unknown handle")
        if _faults().get("unwrap_short"):
            # Contract-violation injection: a malformed, short data key.
            return b"short"
        from keymgr.provider import ProviderInvalidMaterial

        algorithm = entry.get("algorithm")
        material = _unwrap(entry["material"])
        if algorithm == "AES256":
            if wrap_nonce is None or len(wrap_nonce) != 12:
                raise ValueError(
                    "unwrap_key wrap_nonce must be 12 bytes for AES256"
                )
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM

            kek = base64.b64decode(material.encode("ascii"), validate=True)
            try:
                dek = AESGCM(kek).decrypt(wrap_nonce, wrapped_key, None)
            except Exception as exc:
                raise ProviderInvalidMaterial(
                    "wrapped_key cannot be authenticated"
                ) from exc
        elif algorithm == "RSA2048":
            if wrap_nonce is not None:
                raise ValueError(
                    "unwrap_key wrap_nonce must be null for RSA2048"
                )
            private_key = serialization.load_pem_private_key(
                material.encode("utf-8"), password=None
            )
            oaep = padding.OAEP(
                mgf=padding.MGF1(algorithm=hashes.SHA256()),
                algorithm=hashes.SHA256(),
                label=None,
            )
            try:
                dek = private_key.decrypt(wrapped_key, oaep)
            except ValueError as exc:
                raise ProviderInvalidMaterial(
                    "wrapped_key cannot be authenticated"
                ) from exc
        else:
            raise RuntimeError("handle is not a supported algorithm")
        if len(dek) != 32:
            raise ProviderInvalidMaterial(
                "unwrapped data key must be 32 bytes"
            )
        return dek

    def delete(self, handle):
        _check_fault("delete")
        with _lock:
            state = _load_state()
            if handle in state["handles"]:
                del state["handles"][handle]
                _save_state(state)


def make_provider():
    faults = _faults()
    if faults.get("factory_fails"):
        raise RuntimeError("fake factory is failing")
    if faults.get("factory_sleep"):
        time.sleep(float(faults["factory_sleep"]))
    return FakeKmsProvider()

    return idempotent_run(
        op_store, store, path, args.tenant_id, args.operator, body,
        args.idempotency_key, validator, execute, decoder,
        artifact_store=artifact_store,
